import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.D7WGirly.js";const m=JSON.parse('{"title":"Financial Forecast — How-tos & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"financial-forecast-02-how-tos-and-workflows.md","filePath":"financial-forecast-02-how-tos-and-workflows.md"}'),n={name:"financial-forecast-02-how-tos-and-workflows.md"};function l(s,e,r,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="financial-forecast-—-how-tos-workflows" tabindex="-1">Financial Forecast — How-tos &amp; Workflows <a class="header-anchor" href="#financial-forecast-—-how-tos-workflows" aria-label="Permalink to &quot;Financial Forecast — How-tos &amp; Workflows&quot;">​</a></h1><p><em>Step-by-step guides for the most common Financial Forecast workflows</em></p><hr><h2 id="accessing-financial-forecast-for-a-feature" tabindex="-1">Accessing Financial Forecast for a Feature <a class="header-anchor" href="#accessing-financial-forecast-for-a-feature" aria-label="Permalink to &quot;Accessing Financial Forecast for a Feature&quot;">​</a></h2><ol><li>Open the Feature Detail page by clicking a Feature name in the backlog.</li><li>Click the <strong>Financial Forecast</strong> tab (the second tab on the Feature Detail page).</li><li>If no model exists yet, you will see an empty state with options to create one.</li></ol><hr><h2 id="creating-a-model-guided-intake-recommended" tabindex="-1">Creating a Model: Guided Intake (Recommended) <a class="header-anchor" href="#creating-a-model-guided-intake-recommended" aria-label="Permalink to &quot;Creating a Model: Guided Intake (Recommended)&quot;">​</a></h2><p>Guided Intake is the recommended starting point for new models. It walks you through a conversational flow that produces a pre-populated set of assumptions.</p><ol><li>From the Financial Forecast tab, click <strong>Guided Intake</strong> (or the equivalent &quot;Let&#39;s get started&quot; entry point).</li><li>Answer the questions as prompted — the assistant asks about expected costs, revenue impact, timing, and confidence.</li><li>When the intake is complete, Lodestone creates a model with assumptions pre-filled from your answers.</li><li>Review and refine the generated assumptions as needed.</li></ol><blockquote><p><strong>Tip:</strong> Guided Intake is designed to lower the barrier to getting started. You don&#39;t need precise numbers — provide your best estimates and adjust them later as you learn more.</p></blockquote><hr><h2 id="creating-a-model-blank" tabindex="-1">Creating a Model: Blank <a class="header-anchor" href="#creating-a-model-blank" aria-label="Permalink to &quot;Creating a Model: Blank&quot;">​</a></h2><p>If you prefer to build from scratch:</p><ol><li>From the Financial Forecast tab, click <strong>Create Model</strong>.</li><li>A new model is created with your org-level default discount rate. You will land on the model view with an empty assumption list.</li><li>Add assumptions one by one using the <strong>Add Assumption</strong> button.</li></ol><hr><h2 id="adding-an-assumption" tabindex="-1">Adding an Assumption <a class="header-anchor" href="#adding-an-assumption" aria-label="Permalink to &quot;Adding an Assumption&quot;">​</a></h2><ol><li>From the model view, click <strong>Add Assumption</strong> (or the <code>+</code> button).</li><li>Fill in the assumption fields: <ul><li><strong>Name</strong> — a short description of what this assumption represents</li><li><strong>Category</strong> — choose from: Revenue Up, Revenue Down, Cost Up, or Cost Down</li><li><strong>Baseline</strong> — the current value before the Feature ships (enter 0 if there is no baseline)</li><li><strong>Delta</strong> — the change the Feature is expected to produce (a number or percentage)</li><li><strong>Start Month</strong> — which month after launch this impact begins</li><li><strong>Ramp Type</strong> — Immediate (full impact from day one), Linear (builds gradually), or Exponential (accelerates over time)</li><li><strong>Confidence</strong> — High, Medium, or Low</li></ul></li><li>Optionally add Bull and Bear scenario values (see Scenarios below).</li><li>Save. Metrics are recalculated automatically.</li></ol><hr><h2 id="editing-an-assumption" tabindex="-1">Editing an Assumption <a class="header-anchor" href="#editing-an-assumption" aria-label="Permalink to &quot;Editing an Assumption&quot;">​</a></h2><p>Click into any cell in the assumption table to edit it inline. Changes are saved automatically and metrics recalculate immediately.</p><hr><h2 id="deleting-an-assumption" tabindex="-1">Deleting an Assumption <a class="header-anchor" href="#deleting-an-assumption" aria-label="Permalink to &quot;Deleting an Assumption&quot;">​</a></h2><p>Click the delete icon on the assumption row. The assumption is permanently removed and metrics are recalculated.</p><hr><h2 id="setting-bull-and-bear-scenarios" tabindex="-1">Setting Bull and Bear Scenarios <a class="header-anchor" href="#setting-bull-and-bear-scenarios" aria-label="Permalink to &quot;Setting Bull and Bear Scenarios&quot;">​</a></h2><p>For any assumption, you can add optimistic (Bull) and pessimistic (Bear) alternative values.</p><ol><li>Open or expand the assumption.</li><li>Enter a value in the <strong>Bull</strong> field (the optimistic estimate) and the <strong>Bear</strong> field (the pessimistic estimate).</li><li>Save. The model will now show metrics for all three scenarios: Base, Bull, and Bear.</li></ol><p>This is particularly useful when you&#39;re uncertain about a key assumption and want to show a range of outcomes to stakeholders.</p><hr><h2 id="adjusting-the-discount-rate" tabindex="-1">Adjusting the Discount Rate <a class="header-anchor" href="#adjusting-the-discount-rate" aria-label="Permalink to &quot;Adjusting the Discount Rate&quot;">​</a></h2><p>The discount rate affects NPV calculations. It is set per-model and defaults to your org-level setting.</p><ol><li>In the model view, open the <strong>Settings</strong> panel (gear icon or settings link).</li><li>Update the <strong>Discount Rate</strong> field.</li><li>Save. NPV recalculates immediately.</li></ol><hr><h2 id="linking-evidence-to-an-assumption" tabindex="-1">Linking Evidence to an Assumption <a class="header-anchor" href="#linking-evidence-to-an-assumption" aria-label="Permalink to &quot;Linking Evidence to an Assumption&quot;">​</a></h2><p>You can attach customer quotes from the Feature&#39;s quote library to an individual assumption as supporting evidence.</p><ol><li>Open or expand the assumption.</li><li>Click the evidence/link icon.</li><li>Select from the quotes associated with this Feature.</li><li>Save. The linked quotes appear as evidence for that assumption.</li></ol><p>Evidence linking creates an audit trail — it shows which customer signal backs a specific financial estimate.</p><hr><h2 id="switching-between-models" tabindex="-1">Switching Between Models <a class="header-anchor" href="#switching-between-models" aria-label="Permalink to &quot;Switching Between Models&quot;">​</a></h2><p>A Feature can have multiple models. To switch between them:</p><ol><li>From the Financial Forecast tab, use the <strong>Model Selector</strong> dropdown (top of the page).</li><li>Select the model you want to view.</li></ol><hr><h2 id="updating-model-notes" tabindex="-1">Updating Model Notes <a class="header-anchor" href="#updating-model-notes" aria-label="Permalink to &quot;Updating Model Notes&quot;">​</a></h2><p>Each model has an optional context notes field. Use it to document the reasoning, caveats, or scenario descriptions for the model.</p><ol><li>In the model view, find the notes/context area.</li><li>Click to edit and type your notes.</li><li>Changes are saved automatically.</li></ol><hr><h2 id="exporting-a-model-as-excel" tabindex="-1">Exporting a Model as Excel <a class="header-anchor" href="#exporting-a-model-as-excel" aria-label="Permalink to &quot;Exporting a Model as Excel&quot;">​</a></h2><ol><li>From the Financial Forecast tab, click <strong>Export</strong> or the download icon.</li><li>An Excel (.xlsx) file downloads containing the full assumption table, scenario values, and calculated metrics.</li></ol><hr><h2 id="deleting-a-model" tabindex="-1">Deleting a Model <a class="header-anchor" href="#deleting-a-model" aria-label="Permalink to &quot;Deleting a Model&quot;">​</a></h2><ol><li>In the model view, open the Settings panel.</li><li>Select <strong>Delete Model</strong>.</li><li>Confirm. The model and all its assumptions are permanently deleted. This cannot be undone.</li></ol><hr><h2 id="comparing-financial-forecasts-across-features" tabindex="-1">Comparing Financial Forecasts Across Features <a class="header-anchor" href="#comparing-financial-forecasts-across-features" aria-label="Permalink to &quot;Comparing Financial Forecasts Across Features&quot;">​</a></h2><p>To see all Features with financial models ranked by NPV in a single view:</p><ol><li>Navigate to the <strong>Financial Forecast</strong> section at the organization level (accessible from the navigation or a link within the Financial Forecast tab).</li><li>The Compare view shows a table of all Features with models, their key metrics, and model completeness.</li><li>Sort the table by any column to change the ranking.</li></ol><hr><p><em>Next: Advanced Features &amp; Customization — scenarios, evidence, org-level settings, and interpreting metrics.</em></p>',57)])])}const p=a(n,[["render",l]]);export{m as __pageData,p as default};
